<script setup>
import {ref,computed,watch} from 'vue';import {dramaImages} from './images.js';
const props=defineProps({drama:{type:Object,required:true}});const images=computed(()=>dramaImages(props.drama));const index=ref(0),failed=ref(false);
watch(()=>props.drama.id,()=>{index.value=0;failed.value=false;});watch(()=>images.value.join('|'),()=>{index.value=0;failed.value=false;});watch(index,()=>failed.value=false);
function move(n){index.value=(index.value+n+images.value.length)%images.value.length;}
</script>
<template><section v-if="images.length" class="drama-gallery" aria-label="剧集图片"><a :href="images[index]" target="_blank" rel="noopener noreferrer" title="打开原图"><img v-if="!failed" class="drama-main-image" :src="images[index]" :alt="index===0?'剧集主海报':'剧集附图 '+(index+1)" @error="failed=true"><span v-else class="image-failed">图片暂时无法加载，点击查看原链接</span></a><div class="gallery-controls"><button v-if="images.length>1" type="button" @click="move(-1)" aria-label="上一张图片">‹</button><span aria-live="polite">{{index===0?'主海报':'图片 '+(index+1)}} · {{index+1}} / {{images.length}}</span><a :href="images[index]" target="_blank" rel="noopener noreferrer">查看原图 ↗</a><button v-if="images.length>1" type="button" @click="move(1)" aria-label="下一张图片">›</button></div><div v-if="images.length>1" class="gallery-thumbs"><button v-for="(url,i) in images" :key="url" type="button" :class="{active:i===index}" :aria-pressed="i===index" :aria-label="'查看第 '+(i+1)+' 张图片'" @click="index=i"><img :src="url" :alt="i===0?'主海报':'图片 '+(i+1)" loading="lazy"></button></div></section></template>
<style scoped>.drama-gallery{margin:12px 0 20px}.drama-main-image{display:block;width:100%;height:auto;max-height:440px;object-fit:contain;border-radius:8px;background:#f0f2eb}.gallery-controls{display:flex;align-items:center;justify-content:center;gap:16px;margin:10px 0;font-size:12px;color:#7d857d}.gallery-controls button{border:0;background:none;font-size:24px;cursor:pointer;color:#303b35}.gallery-controls a{font-size:12px;color:#4e664d}.gallery-thumbs{display:flex;gap:10px;overflow-x:auto;padding:4px 0}.gallery-thumbs button{flex:0 0 65px;height:80px;border:2px solid transparent;padding:2px;border-radius:6px;background:#f0f2eb;cursor:pointer}.gallery-thumbs button.active{border-color:#4e664d}.gallery-thumbs img{width:100%;height:100%;object-fit:contain}.image-failed{display:grid;place-items:center;min-height:180px;color:#7d857d;font-size:13px}@media(max-width:500px){.drama-main-image{max-height:55dvh}.gallery-controls{gap:10px}}
</style>
